import React, { useState } from 'react';
import './ContactUs.css';

function ContactUs() {
    const [formData, setFormData] = useState({
        name: '',
        email: '',
        phone: '',
        message: ''
    });

    const [submitted, setSubmitted] = useState(false);

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        console.log("Form submitted:", formData);
        setSubmitted(true);
        // Reset form
        setFormData({ name: '', email: '', phone: '', message: '' });
    };

    return (
        <div className="contact-container">
            <h1 className="contact-title">Contact Us</h1>
            <p className="contact-subtitle">We’re here to help. Get in touch with us!</p>

            <div className="contact-grid">
                <form className="contact-form" onSubmit={handleSubmit}>
                    <label>
                        Name:
                        <input type="text" name="name" value={formData.name} onChange={handleChange} required />
                    </label>

                    <label>
                        Email:
                        <input type="email" name="email" value={formData.email} onChange={handleChange} required />
                    </label>

                    <label>
                        Phone:
                        <input type="tel" name="phone" value={formData.phone} onChange={handleChange} />
                    </label>

                    <label>
                        Message:
                        <textarea name="message" rows="4" value={formData.message} onChange={handleChange} required></textarea>
                    </label>

                    <button type="submit">Send Message</button>

                    {submitted && <p className="success-msg">Thank you! We'll get back to you soon.</p>}
                </form>

                <div className="contact-info">
                    <h3>Our Office</h3>
                    <p><strong>Chintamani Group</strong></p>
                    <p>123 Corporate Avenue,<br />Ahmedabad, Gujarat, India</p>
                    <p>Email: <a href="mailto:info@chintamanigroup.com">info@chintamanigroup.com</a></p>
                    <p>Phone: +91-98765-43210</p>
                    <div className="map-placeholder">[ Google Map Embed or Placeholder ]</div>
                </div>
            </div>
        </div>
    );
}

export default ContactUs;
